"""Blindly package response snapshots into a dashboard for human review."""
import argparse
import base64
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parent
MODELS = [('Qwen2.5 · 7B', 'hpc-bio-poetic-20261014'), ('Gemma 3 · 12B', 'hpc-gemma12b-bio-poetic-20261014')]

def build(output):
    models=[]
    for title,name in MODELS:
        p=ROOT/'logs'/name/'responses.json'
        # Blind transfer only. No response values are printed or interpreted.
        models.append({'title':title,'name':name,'limit':1024 if 'gemma12b' in name else 256,'branches':json.loads(p.read_text()) if p.exists() else {}})
    data=base64.b64encode(json.dumps(models,ensure_ascii=False).encode()).decode()
    html=TEMPLATE.replace('__DATA__',data)
    output.parent.mkdir(parents=True,exist_ok=True)
    output.write_text(html)
    print('Dashboard saved; response content was not displayed.')

TEMPLATE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NLA experiment dashboard</title>
<style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#101319;color:#edf1f7}*{box-sizing:border-box}body{margin:0}main{max-width:1240px;margin:auto;padding:48px 28px}a{color:#9dbbff}header{border-bottom:1px solid #303642;padding-bottom:26px}.eyebrow{font-size:12px;letter-spacing:2px;color:#8ea6cd;text-transform:uppercase}h1{font-size:clamp(30px,5vw,52px);letter-spacing:-2px;margin:12px 0}p{line-height:1.6;color:#aab5c6;max-width:850px}.notice{padding:15px 18px;background:#19202b;border:1px solid #303d52;border-radius:12px;margin:24px 0;font-size:14px}.model{margin:34px 0}h2{font-size:24px;margin:0}.modelhead{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.badge{font-size:12px;border-radius:30px;background:#1d4037;color:#9aebcd;padding:7px 12px}.pending{background:#343021;color:#e8d19c}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#191e27;border:1px solid #303642;border-radius:16px;padding:20px;min-width:0}.card h3{font-size:17px;margin:0 0 10px}.desc{font-size:13px;min-height:62px;margin:0 0 18px}.number{font-size:36px;font-weight:650;letter-spacing:-1px}.unit{font-size:13px;color:#95a1b4;margin-left:6px}.bar{height:6px;background:#303642;border-radius:4px;margin:15px 0;overflow:hidden}.fill{height:100%;background:#8faaff}.stop{font-size:12px;color:#adb9ca;min-height:20px}details{margin-top:18px;border-top:1px solid #303642;padding-top:14px}summary{cursor:pointer;color:#b5caff;font-size:13px}.response{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.65;font-size:14px;color:#e2e9f3;max-height:560px;overflow:auto;margin-top:18px}.tools{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}button{cursor:pointer;background:#25334b;color:#dfebff;border:1px solid #435779;border-radius:8px;padding:10px 14px}footer{margin-top:40px;color:#8592a7;font-size:12px}.waiting{color:#9aa8bd;font-size:14px}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){main{padding:28px 16px}.grid{grid-template-columns:1fr}.modelhead{align-items:flex-start;flex-direction:column}}
</style><main><header><div class="eyebrow">Natural language autoencoders · four trajectories</div><h1>Experiment findings so far</h1><p>Compare the generated responses across four independent trajectories. This dashboard presents outputs for your review; no response content has been read or interpreted by the assistant.</p></header><div class="notice">Snapshot, not a live monitor. Qwen is complete. Gemma 12B continues up to its end token or 1,024 tokens. Other model evaluations are stopped. Token counts measure output length, not quality or safety.</div><div class="tools"><button id="expand">Expand all responses</button><button id="collapse">Collapse all responses</button></div><div id="models"></div><footer>Presets: bio_question / poetic · Editor: GPT-6.1 Sol via local subscription · Maximum: Qwen 256 tokens; Gemma 12B 1,024 tokens per trajectory. Responses stay collapsed until you choose to view them. This file contains the response snapshots; share it only as intended.</footer></main>
<script>
const models=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob('__DATA__'),c=>c.charCodeAt(0))));
const specs=[['original','Original','Always choose the next token from the unmodified model.'],['roundtrip','Reconstructed','Choose the next token after reconstructing the activation through the NLA.'],['edited_raw','Edited','Choose the next token from the edited activation.'],['edited_corrected','Edited + error','Choose the next token from the edited activation plus the reconstruction error.']];
const node=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
for(const m of models){const section=node('section','model'),head=node('div','modelhead');head.append(node('h2','',m.title));const completed=specs.every(([key])=>m.branches[key]&&m.branches[key].stop_reason!=='in_progress');head.append(node('span','badge'+(completed?'':' pending'),completed?'All four complete':'Partial results'));section.append(head);const grid=node('div','grid');for(const[key,title,desc]of specs){const b=m.branches[key];const card=node('article','card');card.append(node('h3','',title),node('p','desc',desc));const count=b?.generated_token_ids?.length||0;const num=node('div','number',String(count));num.append(node('span','unit','tokens'));card.append(num);const bar=node('div','bar'),fill=node('div','fill');fill.style.width=Math.min(100,count/m.limit*100)+'%';bar.append(fill);card.append(bar,node('div','stop',!b?'Not started':b.stop_reason==='eos'?'Finished · end of sequence':b.stop_reason==='token_limit'?'Finished · token limit':'In progress'));if(b){const details=node('details');details.append(node('summary','','View response'),node('div','response',b.response));card.append(details)}grid.append(card)}section.append(grid);const link=node('a','','Published snapshot on GitHub');link.href='https://github.com/LucasLista/nla-playground/tree/main/logs/'+m.name;section.append(link);document.getElementById('models').append(section)}
document.getElementById('expand').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=true);document.getElementById('collapse').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=false);
</script></html>'''
if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);build(p.parse_args().output)
